svg.script:
(function () {
  var DUR = 8000;

var basePts = [[658.4,755.8],[695.3,749],[732.1,750.2],[768.9,732.1],[805.8,718.4],[842.6,713.4],[879.4,712.2],[916.3,720.9],[953.1,720.3],[989.9,722.1],[1026.8,713.4],[1063.6,693.4],[1100.4,666],[1137.3,624.8],[1174.1,599.9],[1210.9,562.4],[1247.8,522.5],[1284.6,496.3],[1321.4,473.9],[1358.3,451.4],[1395.1,406.5],[1431.9,339.7],[1468.8,304.2],[1505.6,293]];
var mentionsEl = document.getElementById('fin-mentions');
var deltaEl = document.getElementById('fin-delta');
var lineEl = document.getElementById('fin-line');
var traceEl = document.getElementById('fin-trace');
var areaEl = document.getElementById('fin-area');
var dotEl = document.getElementById('fin-dot');
var haloEl = document.getElementById('fin-halo');
function catmullRom(pList) {
  var d = 'M ' + pList[0][0] + ' ' + pList[0][1];
  for (var i = 0; i < pList.length - 1; i++) {
    var p0 = pList[Math.max(0, i - 1)];
    var p1 = pList[i];
    var p2 = pList[i + 1];
    var p3 = pList[Math.min(pList.length - 1, i + 2)];
    d += ' C ' + (p1[0] + (p2[0] - p0[0]) / 6).toFixed(1) + ' ' + (p1[1] + (p2[1] - p0[1]) / 6).toFixed(1) +
         ', ' + (p2[0] - (p3[0] - p1[0]) / 6).toFixed(1) + ' ' + (p2[1] - (p3[1] - p1[1]) / 6).toFixed(1) +
         ', ' + p2[0].toFixed(1) + ' ' + p2[1].toFixed(1);
  }
  return d;
}
function renderAt(p) {
  var s = Math.sin(2 * Math.PI * p);
  var pts = basePts.map(function (pt, idx) {
    var w = Math.max(0, (idx - 8) / 15);
    var dy = -26 * s * w - 6 * Math.sin(2 * Math.PI * (p + idx * 0.06)) * (0.4 + w * 0.6);
    return [pt[0], Number((pt[1] + dy).toFixed(1))];
  });
  var d = catmullRom(pts);
  var a = d + ' L ' + pts[pts.length - 1][0].toFixed(1) + ' 792 L ' + pts[0][0].toFixed(1) + ' 792 Z';
  if (lineEl) lineEl.setAttribute('d', d);
  if (traceEl) traceEl.setAttribute('d', d);
  if (areaEl) areaEl.setAttribute('d', a);
  var peak = pts[pts.length - 1];
  if (dotEl) dotEl.setAttribute('cy', peak[1].toFixed(1));
  if (haloEl) {
    haloEl.setAttribute('cy', peak[1].toFixed(1));
    haloEl.style.transformOrigin = peak[0].toFixed(1) + 'px ' + peak[1].toFixed(1) + 'px';
  }
  var kVal = 80.0 + 4.8 * s;
  var dk = 8.2 + (kVal - 80.0);
  var pct = 11.4 + ((kVal - 80.0) / 71.8) * 100;
  if (mentionsEl) mentionsEl.textContent = kVal.toFixed(1) + 'K';
  if (deltaEl) deltaEl.textContent = '↑' + dk.toFixed(1) + 'K  +' + pct.toFixed(1) + '%';
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
